    return time.perf_counter() * 1000


class RulesBuilder:
    def __init__(self, src: str, limit: int = 1000):
        self.pos = 0
        self.symbol_ids = SymbolIds()
        self.rules: List[Optional[List[InternalRuleDef]]] = []
        self.src = src
        self.start = _now()
        self._time_limit = limit
        self.parse(src)

    def parse(self, src: str) -> None:
