import json

from .type_guards import is_rule_char, is_rule_char_excluded, is_rule_end, is_rule_ref
from .types import RuleType

KEY_TRANSLATION = {
    RuleType.END.value: 0,
    RuleType.CHAR.value: 1,
    RuleType.CHAR_EXCLUDE.value: 2,
}


def get_serialized_rule_key(rule) -> str:
    if is_rule_end(rule):
        return f"{KEY_TRANSLATION[RuleType.END.value]}"

    if is_rule_char(rule) or is_rule_char_excluded(rule):
        value = json.dumps(rule.value, separators=(",", ":"))
        return f"{KEY_TRANSLATION[rule.type]}-{value}"

    if is_rule_ref(rule):
        return f"3-{rule.value}"

    raise Exception(f"Unknown rule type: {rule!r}")
