    ],
    [
      'arithmetic',
      'and',
      'root  ::= (expr "=" ws term "\\n")+\\nexpr  ::= term ([-+*/] term)*\\nterm  ::= ident | num | "(" ws expr ")" ws\\nident ::= [a-z] [a-z0-9_]* ws\\nnum   ::= [0-9]+ ws\\nws    ::= [ \\t\\n]*\\n',
    ],
    [
      'arithmetic',
      '1 +2',
      'root  ::= (expr "=" ws term "\\n")+\\nexpr  ::= term ([-+*/] term)*\\nterm  ::= ident | num | "(" ws expr ")" ws\\nident ::= [a-z] [a-z0-9_]* ws\\nnum   ::= [0-9]+ ws\\nws    ::= [ \\t\\n]*\\n',
    ],
    [
